using UnityEngine;
using UnityEngine.XR.ARFoundation;
using UnityEngine.XR.ARSubsystems;

public class ARController : MonoBehaviour
{
    public ARSession session;
    public ARPlaneManager planeManager;
    public ARRaycastManager raycastManager;
    public GameObject placementPrefab;
    private List<ARRaycastHit> hits = new List<ARRaycastHit>();

    void Start()
    {
        // Check AR availability
        if (ARSession.state == ARSessionState.None ||
            ARSession.state == ARSessionState.CheckingAvailability)
        {
            StartCoroutine(CheckARSupport());
        }

        // Configure plane detection
        planeManager.planeDetectionMode = PlaneDetectionMode.Horizontal;
        planeManager.requestedDetectionMode = PlaneDetectionMode.Horizontal;
    }

    IEnumerator CheckARSupport()
    {
        yield return ARSession.CheckAvailability();
        if (ARSession.state == ARSessionState.Unsupported)
        {
            Debug.LogError("AR not supported on this device");
        }
    }

    void Update()
    {
        if (Input.touchCount > 0 && Input.GetTouch(0).phase == TouchPhase.Began)
        {
            Vector2 touchPos = Input.GetTouch(0).position;

            if (raycastManager.Raycast(touchPos, hits, TrackableType.PlaneWithinPolygon))
            {
                Pose hitPose = hits[0].pose;
                Instantiate(placementPrefab, hitPose.position, hitPose.rotation);
            }
        }
    }

    public void TogglePlaneDetection(bool enable)
    {
        planeManager.enabled = enable;
        foreach (var plane in planeManager.trackables)
            plane.gameObject.SetActive(enable);
    }

    public void ResetARSession()
    {
        session.Reset();
    }

    void OnEnable() => planeManager.planesChanged += OnPlanesChanged;
    void OnDisable() => planeManager.planesChanged -= OnPlanesChanged;

    void OnPlanesChanged(ARPlanesChangedEventArgs args)
    {
        foreach (var plane in args.added)
            Debug.Log($"Plane detected: {plane.trackableId}");
    }
}

