using UnityEngine;
using UnityEngine.SceneManagement;
using System.Collections;

public class SceneLoader : MonoBehaviour
{
    public static SceneLoader Instance;

    void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }
        else
        {
            Destroy(gameObject);
        }
    }

    IEnumerator Start()
    {
        // Load persistent UI scene
        string uiScene = "UIRoot";
        if (!SceneManager.GetSceneByName(uiScene).isLoaded)
        {
            var op = SceneManager.LoadSceneAsync(uiScene, LoadSceneMode.Additive);
            yield return op;
        }
    }

    public void LoadLevel(string levelName)
    {
        StartCoroutine(SwitchLevel(levelName));
    }

    IEnumerator SwitchLevel(string newLevel)
    {
        // Load new level
        var loadOp = SceneManager.LoadSceneAsync(newLevel, LoadSceneMode.Additive);
        yield return loadOp;

        Scene newScene = SceneManager.GetSceneByName(newLevel);
        SceneManager.SetActiveScene(newScene);

        // Unload previous gameplay scenes
        for (int i = 0; i < SceneManager.sceneCount; i++)
        {
            Scene s = SceneManager.GetSceneAt(i);
            if (s.name != "UIRoot" && s.name != newLevel)
            {
                var unloadOp = SceneManager.UnloadSceneAsync(s);
                yield return unloadOp;
            }
        }
    }

    void OnEnable() => SceneManager.sceneLoaded += OnSceneLoaded;
    void OnDisable() => SceneManager.sceneLoaded -= OnSceneLoaded;

    void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        Debug.Log($"Loaded {scene.name} ({mode})");
    }
}

