using UnityEngine;
using UnityEngine.AI;

public class AIController : MonoBehaviour
{
    private NavMeshAgent agent;
    public Transform target;
    public float updateRate = 0.5f;
    private float lastUpdate;

    void Start()
    {
        agent = GetComponent<NavMeshAgent>();
        agent.speed = 5f;
        agent.angularSpeed = 360f;
        agent.stoppingDistance = 1.5f;
        agent.autoBraking = true;
        agent.radius = 0.5f;
        agent.height = 2f;
    }

    void Update()
    {
        if (target && Time.time > lastUpdate + updateRate)
        {
            agent.SetDestination(target.position);
            lastUpdate = Time.time;
        }

        // Path status
        if (agent.pathStatus == NavMeshPathStatus.PathPartial)
        {
            Debug.LogWarning("Cannot reach target — path partial");
        }

        // Agent avoidance
        if (agent.pathPending) return;
    }

    void OnAnimatorMove()
    {
        // Root motion with NavMeshAgent
        if (agent.remainingDistance > agent.stoppingDistance)
            agent.velocity = animator.deltaPosition / Time.deltaTime;
    }

    // Dynamic NavMesh baking
    void BakeRuntimeArea(Bounds area)
    {
        var surface = FindObjectOfType<NavMeshSurface>();
        surface.Bake();
    }
}

