using Unity.Entities;
using Unity.Transforms;
using Unity.Mathematics;
using Unity.Burst;
using Unity.Jobs;
using Unity.Collections;

// Component (pure data)
public struct Velocity : IComponentData
{
    public float3 Value;
}

// System that runs every frame
[BurstCompile]
partial struct MovementSystem : ISystem
{
    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        float dt = SystemAPI.Time.DeltaTime;
        new MovementJob { dt = dt }.ScheduleParallel();
    }
}

[BurstCompile]
partial struct MovementJob : IJobEntity
{
    public float dt;

    void Execute(ref LocalTransform transform, in Velocity velocity)
    {
        transform.Position += velocity.Value * dt;
    }
}

// Parallel job (non-ECS)
[BurstCompile]
struct UpdatePositionsJob : IJobParallelFor
{
    public NativeArray<Vector3> positions;
    public NativeArray<Vector3> velocities;
    public float deltaTime;

    public void Execute(int i)
    {
        positions[i] += velocities[i] * deltaTime;
        if (positions[i].y < 0)
        {
            positions[i].y = 0;
            velocities[i].y *= -0.5f;
        }
    }
}

void Update()
{
    var job = new UpdatePositionsJob
    {
        positions = positionsArray,
        velocities = velocitiesArray,
        deltaTime = Time.deltaTime
    };
    JobHandle handle = job.Schedule(positionsArray.Length, 64);
    handle.Complete();
}

