        for (int i = 0; i < 10; i++)
        {
            instances[i] = new TreeInstance
            {
                position = new Vector3(Random.Range(0f, 1f), 0, Random.Range(0f, 1f)),
                widthScale = Random.Range(0.8f, 1.2f),
                heightScale = Random.Range(0.8f, 1.2f),
